namespace App\Http\Controllers\Pharmacy;

use App\Http\Controllers\Controller;
use App\Models\PrescriptionRefillRequest;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;

class RefillApprovalController extends Controller
{
    public function approve(Request $request, int $refillId): JsonResponse
    {
        if (!$request->user()->tokenCan('prescriptions:refill')) {
            return response()->json(['error' => 'Refill approval scope required'], 403);
        }

        $refill = $request->user()->pharmacyBranch
            ->prescriptionRefillRequests()
            ->findOrFail($refillId);

        $this->authorize('approveRefill', $refill);
        $refill->update(['status' => 'approved', 'approved_at' => now()]);

        return response()->json(['message' => 'Refill approved', 'refill' => $refill]);
    }
}
